@push('scripts')<script>
(function(){const inputs=document.querySelectorAll('.jc-denom');const corte=document.getElementById('jc-corte');const fmt=n=>'Q '+(n/100).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2});function calcular(){let total=0;inputs.forEach(el=>{const cantidad=Math.max(0,Math.trunc(Number(el.value)||0));const subtotal=cantidad*Number(el.dataset.centavos);el.closest('tr').querySelector('.jc-subtotal').textContent=fmt(subtotal);total+=subtotal;});const centavos=Math.round((Number(corte.value)||0)*100);const dif=total-centavos;document.getElementById('jc-total').textContent=fmt(total);document.getElementById('jc-diferencia').textContent=(dif<0?'-':'')+fmt(Math.abs(dif));document.getElementById('jc-justificacion').required=dif!==0;}inputs.forEach(el=>el.addEventListener('input',calcular));corte.addEventListener('input',calcular);calcular();document.getElementById('jc-create-form').addEventListener('submit',function(e){if(!confirm('¿Confirma el registro y la firma electrónica de este arqueo?')){e.preventDefault();return;}document.getElementById('jc-submit').disabled=true;});})();
</script>@endpush
